return UnityEditor.AssetDatabase.FindAssets("t:Model",new[]{"Assets/_Game/Animations/Shared"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).Select(p=>new{path=p,rig=((UnityEditor.ModelImporter)UnityEditor.AssetImporter.GetAtPath(p)).animationType.ToString(),bones=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(p).GetComponentsInChildren<UnityEngine.Transform>(true).Select(t=>t.name).Take(7).ToArray(),clips=UnityEditor.AssetDatabase.LoadAllAssetsAtPath(p).OfType<UnityEngine.AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).Select(c=>new{c.name,c.length,c.isHumanMotion}).ToArray()}).ToArray();
